import assert from 'node:assert/strict';import {chromium} from 'playwright-core';
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--disable-gpu','--no-first-run']});const page=await browser.newPage({viewport:{width:1600,height:980}});
try{await page.goto('http://127.0.0.1:5977/?desktop=1&engine=clothcraft&testSession=hidden-idle-dock-20261028',{waitUntil:'domcontentloaded'});await page.locator('.main-layout').waitFor();await page.getByRole('combobox',{name:'3D and 2D window arrangement'}).selectOption('2d');const host=page.locator('.main-layout>.exo-global-grade-dock-host');await host.waitFor({state:"attached"});const measure=()=>host.evaluate(node=>({height:node.getBoundingClientRect().height,rail:getComputedStyle(node.querySelector('.exo-bottom-dock-rail')).display,occupied:node.dataset.exoGradeDockOccupied,hover:node.dataset.exoGradeDockDragHover}));const idle=await measure();assert(idle.height<=1&&idle.rail==='none',JSON.stringify(idle));await page.evaluate(()=>window.dispatchEvent(new CustomEvent('exo-clothcraft-pattern-studio-command',{detail:{command:'grade-table'}})));const widget=page.locator('.exo-grade-bottom-widget[data-exo-grade-bottom-widget="values"]');await widget.locator('.exo-grade-widget-placement').selectOption('bottom');await page.waitForTimeout(120);const occupied=await measure();assert(occupied.height>170&&occupied.occupied==='true',JSON.stringify(occupied));await widget.getByRole('button',{name:'Undock Grading Table'}).click();await page.waitForTimeout(120);const after=await measure();assert(after.height<=1&&after.rail==='none',JSON.stringify(after));console.log(JSON.stringify({ok:true,idle,occupied,after},null,2));}finally{await browser.close()}
